fix code // groupsEran fetches eutran cells data from Atoll by name according to new name policy fro Elastic Ran
func (r *EUtranCellRepository) groupsEran(name string, owners []string) (model.EUtranCellsGroups, error) {
	groups := make(model.EUtranCellsGroups)
	// Create a new slice to store valid owners
	for _, cellsGroupLabel := range owners {
		cells, err := r.cellsv2(name, cellsGroupLabel)
		if err != nil {
			//Catch error as sting in cells var
			groups[cellsGroupLabel] = errors.New("No cells found")
			continue
		}
		groups[cellsGroupLabel] = cells
	}
	groups.RemoveEmpty()
	return groups, nil
}

