void servo_degress_points_to_move(Point points[], int points_num, int step_tot, float step_time) {
int loop = 1;
int point_n = 0;
int step_n = 0;
int last_points_num = points_num - 1;
while (loop) {
float ro, pi;
if (point_n == last_points_num) {
ro = (points[0].ro - points[last_points_num].ro) / step_tot * step_n + points[last_points_num].ro;
pi = (points[0].pi - points[last_points_num].pi) / step_tot * step_n + points[last_points_num].pi;
} else {
ro = (points[point_n+1].ro - points[point_n].ro) / step_tot * step_n + points[point_n].ro;
pi = (points[point_n+1].pi - points[point_n].pi) / step_tot * step_n + points[point_n].pi;
}
laser_move_by_degress(ro, pi);
step_n += 1;
if (step_n > step_tot) {
step_n = 0;
point_n += 1;
if (point_n > last_points_num) {
point_n = 0;
}
}
delay_ms(step_time);
}
}
