------------------------------------------------------------------------------------------------- */
int16 HW_One_PI(int16 Xn1)
{
    PI_EK =  Xn1;                                               /* filling-in Err */
    SetBit(PI_CR, PISTA);                                       /* Start PI Module */
    _nop_();
    _nop_();
    _nop_();
    _nop_();
    return PI_UK;
}



/*---------------------------------------------------------------------------*/
/* Name		:	void VSPSample(void)
/* Input	:	NO
